describe('Unsaved Form Navigation Warning', () => {
    beforeEach(() => {
        cy.visit('/form'); // Replace with the actual form URL
    });

    it('should display a warning when trying to navigate away with unsaved changes', () => {
        cy.get('input[name="exampleField"]').type('Some unsaved data');
        cy.window().then((win) => {
            cy.stub(win, 'confirm').returns(true); // Simulate user confirming the navigation
        });
        cy.get('a[href="/another-page"]').click(); // Replace with the actual link to navigate away
        cy.on('window:alert', (str) => {
            expect(str).to.equal('You have unsaved changes. Are you sure you want to leave?');
        });
    });

    it('should not display a warning when navigating away after saving', () => {
        cy.get('input[name="exampleField"]').type('Some data');
        cy.get('button[type="submit"]').click(); // Assuming there's a submit button to save the form
        cy.get('a[href="/another-page"]').click(); // Replace with the actual link to navigate away
        cy.url().should('include', '/another-page'); // Verify that the navigation occurred
    });
});
